sys_ux_data_broker_transform.required_translations:
[ {
  "message" : "Enter the Table Name",
  "comment" : ""
}, {
  "message" : "Enter the filter for Table",
  "comment" : ""
} ]

sys_ux_data_broker_transform.script:
function transform(input) {
 let tableName = input.tableName;
 let filter = input.filter;

if(!tableName){
        gs.log("Error: No table Name specified");
        return { "error": "An error occurred while fetching data: " };
    }

try {
        var gr = new GlideRecord(tableName);
		if(filter){
		gr.addEncodedQuery(filter);
		}
        gr.query();


        var result = [];

        // Iterate through the records and collect data
        while (gr.next()) {
            var recordObj = {};
            var fields = gr.getFields();
			recordObj['sys_id'] = gr.getUniqueValue();

            for (var i = 0; i < fields.size(); i++) {
                var fieldName = fields.get(i).getName();
                recordObj[fieldName] = gr.getValue(fieldName);
            }

            result.push(recordObj); // Push the record to the result array
        }

        gs.log("Result: " + JSON.stringify(result));
        return result;

    } catch (e) {
        gs.log("Error: " + e.toString());
        return { error: "An error occurred while fetching data: " + e.toString() };
    }



}
